ACME-DOC-010 Rev D 
123 

function run() 
{  
   //The keyword ‘running’ is important for the ground software. 
   print("BasicScript running");   

   if ( parameters.parameter1 != 5 ) 
   { 

// do something 
   } 

   // examples of filling in command parameters and sending to main program 
   FlowSetSolenoidValveState.solendoidValve = 3; 
   FlowSetSolenoidValveState.state = 1; 
   sendCommand(FlowSetSolenoidValveState); 

   // example of looking at current telemetry 
   If ( FlowTelemetry.MFCA3FuelFlowSlpm > parameters.parameter3) 
   { 

// do something 
   } 

   // script can pause itself. No parameters. 
  sendCommand(PauseScript); 
  print(“Script is paused.  Press resume when ready.”); 

   // now operator must issue ResumeScript command from ground 

   // call a function in this file 
  doSomethingElse(); 

   // the keyword ‘completed’ is important for the ground software. 
   Print(“BasicScript completed”); 
} 

Function doSomethingElse() 
{ 

// more code 
}
